    "original_url": "https://radiodalsan.com/2026/07/27/northeastern-state-parliament-demands-trials-for-goojaadde-detainees/?utm_source=rss&#038;utm_medium=rss&#038;utm_campaign=northeastern-state-parliament-demands-trials-for-goojaadde-detainees",
    "country": "Somalia",
    "category": "Politics",
